import Foundation

/// Strict Java/Android GBK, independent of unavailable iOS NSString codecs.
/// The mapping is generated by native_tests/GenerateGBKMap.java.
struct WenkuGBK {
  private let mapping: [UInt16: UInt16]

  init(mapping data: Data) throws {
    guard !data.isEmpty, data.count % 4 == 0, data.count <= 65536 * 4 else {
      throw WenkuProtocolError.invalidInput
    }
    let bytes = Array(data)
    var map = [UInt16: UInt16]()
    map.reserveCapacity(bytes.count / 4)
    var previous: UInt16 = 127
    for offset in stride(from: 0, to: bytes.count, by: 4) {
      let scalar = UInt16(bytes[offset]) << 8 | UInt16(bytes[offset + 1])
      let encoded = UInt16(bytes[offset + 2]) << 8 | UInt16(bytes[offset + 3])
      guard scalar > previous, !(0xD800...0xDFFF).contains(scalar), encoded > 0 else {
        throw WenkuProtocolError.invalidInput
      }
      map[scalar] = encoded
      previous = scalar
    }
    mapping = map
  }

  func review(_ text: String) throws -> String {
    guard text.utf16.count <= 10000 else { throw WenkuProtocolError.invalidInput }
    var bytes = [UInt8]()
    for scalar in text.unicodeScalars {
      if scalar.value < 128 {
        bytes.append(UInt8(scalar.value))
      } else {
        guard scalar.value <= 0xFFFF, let value = mapping[UInt16(scalar.value)] else {
          throw WenkuProtocolError.encoding
        }
        if value > 0xFF { bytes.append(UInt8(value >> 8)) }
        bytes.append(UInt8(value & 0xFF))
      }
    }
    let safe = Set("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789.-*_".utf8)
    let escaped = bytes.map { byte -> String in
      if byte == 32 { return "+" }
      if safe.contains(byte) { return String(UnicodeScalar(byte)) }
      return String(format: "%%%02X", byte)
    }.joined()
    return Data(escaped.utf8).base64EncodedString()
  }
}
